(9417001, 0, 0, 'Open the portal to Karazhan.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, NULL),
(9417002, 0, 0, 'Open the portal to Dalaran Crater.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, NULL),
(9417002, 1, 0, 'Send me home to Stormwind.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, NULL),
(9417002, 2, 0, 'Send me home to Orgrimmar.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, NULL),
(9417003, 0, 0, 'Take me back to the Guardian''s Library.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, NULL),
(9417004, 0, 0, 'Ask: "What troubles Khadgar?"', 0, 1, 1, 9417005, 0, 0, 0, NULL, 0, NULL),
(9417006, 0, 0, 'I am ready - lead the way.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, NULL),
(9417007, 0, 0, 'I am ready - lead the way.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, NULL),
(9417007, 1, 0, 'I am ready - let us go on.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, NULL),
